{"command": "# Check the releases index for .NET 11
curl -s "https://dotnetcli.azureedge.net/dotnet/release-metadata/releases-index.json" | python3 -c "
import json, sys
data = json.load(sys.stdin)
for rel in data.get('releases-index', []):
    ver = rel.get('channel-version', '')
    if ver.startswith('11') or ver.startswith('10') or ver.startswith('9'):
        print(f\"{ver} -> {rel.get('releases.json', '')}\")" 2>/dev/null | head -20", "description": "Check .NET releases index"}
